import sys

def count_ones_binary(x):
    """Count the number of 1s in the binary representation of x"""
    count = 0
    while x > 0:
        count += x & 1
        x >>= 1
    return count

def main():
    x = int(sys.stdin.readline())
    print(count_ones_binary(x))

if __name__ == "__main__":
    main()
"}

