import sys

def is_good(points, index):
    """Check if the point at given index is good"""
    n = len(points)
    # Get the point
    a = points[index]
    # Check all pairs of other points
    for i in range(n):
        if i == index:
            continue
        for j in range(i + 1, n):
            if j == index:
                continue
            # Get vectors ab and ac
            b = points[i]
            c = points[j]
            # Vector ab = b - a
            ab = (b[0] - a[0], b[1] - a[1], b[2] - a[2], b[3] - a[3], b[4] - a[4])
            # Vector ac = c - a
            ac = (c[0] - a[0], c[1] - a[1], c[2] - a[2], c[3] - a[3], c[4] - a[4])
            # Compute dot product
            dot = ab[0] * ac[0] + ab[1] * ac[1] + ab[2] * ac[2] + ab[3] * ac[3] + ab[4] * ac[4]
            if dot > 0:
                return False  # Found an acute angle
    return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    points = []
    for i in range(n):
        coords = [int(next(it)) for _ in range(5)]
        points.append(tuple(coords))

    good_points = []
    for i in range(n):
        if is_good(points, i):
            good_points.append(i + 1)  # 1-indexed

    print(len(good_points))
    for p in good_points:
        print(p)

if __name__ == "__main__":
    main()
"}

