import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    a = [0] * n
    for i in range(n):
        a[i] = int(next(it))

    # Union-find for each bit
    bits = 21  # since max value is 300000, which fits in 21 bits
    parent = [i for i in range(n + 1)]  # 1-indexed

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        pu = find(u)
        pv = find(v)
        if pu != pv:
            parent[pu] = pv

    # For each bit, merge positions if both have that bit set
    for bit in range(bits):
        # Find all positions with this bit set
        positions = []
        for i in range(n):
            if a[i] & (1 << bit):
                positions.append(i + 1)  # 1-indexed

        # Merge consecutive positions with this bit set
        for i in range(len(positions) - 1):
            union(positions[i], positions[i + 1])

    # Answer queries
    out = []
    for _ in range(q):
        x = int(next(it))
        y = int(next(it))

        # Check if there's any bit where x and y are in the same component
        found = False
        for bit in range(bits):
            if find(x) == find(y):
                found = True
                break

        out.append("Shi" if found else "Fou")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
"}

