import sys

def max_consec(row):
    max_len = 0
    curr_len = 0
    for x in row:
        if x == 1:
            curr_len += 1
        else:
            max_len = max(max_len, curr_len)
            curr_len = 0
    return max(max_len, curr_len)

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    q = int(next(it))
    grid = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        grid.append(row)
    out_lines = []
    for _ in range(q):
        i = int(next(it)) - 1
        j = int(next(it)) - 1
        grid[i][j] ^= 1  # flip
        max_row = 0
        for r in range(n):
            curr_row_max = max_consec(grid[r])
            if curr_row_max > max_row:
                max_row = curr_row_max
        out_lines.append(str(max_row))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

