def can_achieve(n, k, a):
    used = set()

    for value in a:
        # Find powers of k that sum to value
        powers = []
        power = 1  # k^0
        while power <= value:
            powers.append(power)
            power *= k

        # Try to use the largest power first
        powers.sort(reverse=True)

        for p in powers:
            if p not in used:
                used.add(p)
                value -= p
            else:
                # This power is already used, fail
                return False

        if value != 0:
            # Couldn't form the value with available powers
            return False

    return True

def solve():
    import sys
    input = sys.stdin.read().split()
    data = iter(input)

    T = int(next(data))

    for _ in range(T):
        n = int(next(data))
        k = int(next(data))
        a = [int(next(data)) for _ in range(n)]

        if can_achieve(n, k, a):
            print("YES")
        else:
            print("NO")

if __name__ == "__main__":
    solve()
