    s = sys.stdin.readline().strip()
    grid = [[False for _ in range(4)] for _ in range(4)]
    deleted_rows = set()
    deleted_cols = set()

    for i, ch in enumerate(s):
        # Find a valid position for the tile
        placed = False
        for r in range(4):
            if r in deleted_rows:
                continue
            for c in range(4):
                if c in deleted_cols:
                    continue
                # Check if we can place the tile at (r, c)
                if ch == '0':  # vertical tile
                    # Check if cells (r, c) and (r+1, c) are empty
                    if not grid[r][c] and not grid[r+1][c]:
                        # Place the tile
                        grid[r][c] = True
                        grid[r+1][c] = True

                        # Check if any row/column is fully occupied
                        # Check rows
                        for row in range(4):
                            if row in deleted_rows:
                                continue
                            if all(grid[row][col] for col in range(4)):
