def solve():
    n = int(input())
    events = []
    for _ in range(n):
        parts = input().split()
        events.append((parts[0], int(parts[1])))

    # dp[i][has][stick] = max earnings from day i onwards
    # has: 0 = no stick, 1 = has stick
    # stick: 0..2000 (or 2001 for no stick)
    INF = 10**18
    dp = [[[INF] * (2001 + 1) for _ in range(2)] for _ in range(n + 1)]

    # Base case: after last day, no earnings
    for has in range(2):
        for stick in range(2001 + 1):
            dp[n][has][stick] = 0

    for i in range(n - 1, -1, -1):
        event_type, x = events[i]

        if event_type == 'win':
            # Case 1: Bob keeps the stick he wins
            # If he had no stick before, dp[i][1][x] = dp[i+1][0][2001] + 0
            # If he had stick y before, dp[i][1][x] = dp[i+1][1][y] + 0
            # But we need to iterate through all possible previous sticks
            for has_prev in range(2):
                for stick_prev in range(2001 + 1):
                    if has_prev == 1:
                        # He has a stick, so we update dp[i][1][x]
                        # After winning, he keeps the new stick
                        dp[i][1][x] = max(dp[i][1][x], dp[i+1][1][stick_prev] + 0)
                    else:
                        # He doesn't have a stick, so we update dp[i][1][x]
                        dp[i][1][x] = max(dp[i][1][x], dp[i+1][0][2001] + 0)

            # Case 2: Bob gives away the stick he wins
            # If he had no stick before, dp[i][0][2001] = dp[i+1][0][2001] + 0
            # If he had stick y before, dp[i][0][2001] = dp[i+1][1][y] + 0
            for has_prev in range(2):
                for stick_prev in range(2001 + 1):
                    if has_prev == 1:
                        # He had a stick, so after giving it away he has no stick
                        dp[i][0][2001] = max(dp[i][0][2001], dp[i+1][1][stick_prev] + 0)
                    else:
                        # He doesn't have a stick, he still has no stick
                        dp[i][0][2001] = max(dp[i][0][2001], dp[i+1][0][2001] + 0)
