import sys
from collections import defaultdict, deque

def is_bipartite(adj, n):
    color = [-1] * n
    for start in range(n):
        if color[start] == -1:
            queue = deque([start])
            color[start] = 0
            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        return False, -1
    return True, color

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    points = [int(next(it)) for _ in range(n)]

    adj = defaultdict(set)

    for _ in range(m):
        l = int(next(it))
        r = int(next(it))
        count = 0
        for i, p in enumerate(points):
            if l <= p <= r:
                count += 1
        if count % 2 == 1:
            # Need to create conflicts between all pairs of points in this segment
            # For simplicity, we'll connect all points to one central point
            # This works because we need to choose an extra point
            # If there are k points with odd count, we need one to be extra
            # Connect all points to one central point (we'll pick the first one)
            if count > 0:
                central = next(i for i, p in enumerate(points) if l <= p <= r)
                for i, p in enumerate(points):
                    if l <= p <= r and i != central:
                        adj[central].add(i)

    is_bip, color = is_bipartite(adj, n)
    if not is_bip:
        print(-1)
    else:
        # Output the colors
        print(' '.join(map(str, color)))

solve()
