import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n = int(sys.stdin.readline())
        codes = [sys.stdin.readline().strip() for _ in range(n)]

        # Check if all codes are already distinct
        if len(set(codes)) == n:
            print(0)
            for code in codes:
                print(code)
            continue

        # If not, we need to change digits
        # Let's try to make them distinct greedily
        changed = 0
        result = []

        # Keep track of which codes are still valid
        valid = set(codes)

        for i in range(n):
            if codes[i] in valid:
                result.append(codes[i])
                valid.remove(codes[i])
            else:
                # Need to change this code
                # Find the first position where we can change a digit
                changed += 1
                new_code = codes[i]

                # Try changing each digit to make it unique
                for pos in range(4):
                    for digit in '0123456789':
                        if digit != new_code[pos]:
                            new_code = new_code[:pos] + digit + new_code[pos+1:]
                            result.append(new_code)
                            valid.remove(new_code)
                            break
                    else:
                        continue
                    break

        print(changed)
        for code in result:
            print(code)

if __name__ == "__main__":
