def solve():
    n, q = map(int, input().split())

    # Find the height h such that n = 2^h - 1
    # This means n + 1 is a power of 2
    # Find the power of 2 that is n + 1
    height = 0
    temp = n + 1
    while temp & 1 == 0:
        height += 1
        temp >>= 1

    # The root is at position 2^(h-1)
    root = 1 << (height - 1)

    def move(u, dir):
        """Move in the given direction and return the new position"""
        if dir == 'L':
            # Left child
            if u > root:
                return u - root
            elif u < root:
                return u + root
            else:
                # root has no left child
                return u
        elif dir == 'R':
            # Right child
            if u < root:
                return u + root
            elif u > root:
                return u + root
            else:
                # root has no right child
                return u
        elif dir == 'U':
            # Parent
            if u == root:
                # root has no parent
                return u
            elif u < root:
                return u + root
            elif u > root:
                return u - root

    for _ in range(q):
        u = int(input())
        s = input().strip()

        v = u
        for c in s:
            v = move(v, c)

        print(v)

