        u = int(data[idx+1])
        c = data[idx+2]
        graph[v].append((u, c))
        edges.append((v, u, c))
        idx += 3

    # Topological sort
    in_degree = [0] * (n + 1)
    for v, u, _ in edges:
        in_degree[u] += 1

    topo_order = []
    q = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            q.append(i)

    while q:
        u = q.popleft()
        topo_order.append(u)
        for v, _, _ in edges:
            if v == u:
                in_degree[w] -= 1
                if in_degree[w] == 0:
                    q.append(w)

    # DP table: dp[u][v][last_char] = 'A' or 'B'
    # We'll use a dictionary for efficiency
    dp = {}

    # Process in reverse topological order
    for u in reversed(topo_order):
        for v in reversed(topo_order):
            # Consider all possible last characters (including a special value for first move)
            # Let's use ord('a') - 1 as the special value for first move

            # Max's turn
            max_win = False
            for (v_next, c) in graph[u]:
                last_char = ord(c)
                state = (v, v_next, last_char)
                if state not in dp:
                    continue
                if dp[state] == 'A':
                    max_win = True
                    break

            # Lucas's turn
            lucas_win = False
            for (u_next, c) in graph[v]:
                last_char = ord(c)
                state = (u_next, u, last_char)
                if state not in dp:
                    continue
                if dp[state] == 'B':
                    lucas_win = True
                    break

            # Determine outcome
            if max_win:
                dp[(u, v, ord('a') - 1)] = 'A'
            else:
                dp[(u, v, ord('a') - 1)] = 'B'

