                if t == 0:
                    h = initial_health_global + regen_global * t
                else:
                    h = initial_health_global + regen_global * t
                if h <= 1000:
                    gold = 1000 + 10 * t
                    if gold > max_gold:
                        max_gold = gold

        # Check update times themselves
        for t, h_update in updates[i].items():
            h = h_update
            if h <= 1000:
                gold = 1000 + 10 * t
                if gold > max_gold:
                    max_gold = gold

            # Also consider times after update but before next update
            if t < update_times[-1]:
                next_t = update_times[update_times.index(t) + 1]
                for next_time in range(t + 1, next_t):
