def parse_time(time_str):
    h, m, s = map(int, time_str.split(':'))
    return h * 3600 + m * 60 + s

def solve():
    n, M, T = map(int, input().split())
    queries = []
    for _ in range(n):
        time_str = input().strip()
        queries.append((parse_time(time_str), T))

    # We'll track for each user: (start, end)
    users = []  # list of tuples (start, end)
    user_id = 1

    # Track which users are online at each time
    # We'll use a dictionary to count users online at each time
    online_at = {}

    for i, (s, t) in enumerate(queries):
        end = s + t - 1

        # Check if this query can be assigned to an existing user
        assigned = False
        for j, (start, end_user) in enumerate(users):
            # Check if intervals overlap
            if not (end_user < s or start > end):
                # Can be assigned to this user
                users[j] = (start, end)
                assigned = True
                break

        if not assigned:
            # Create new user
            users.append((s, end))
            user_id += 1

        # Update online_at
        # For the new interval [s, end], increment count for each second
        for time in range(s, end + 1):
            if time in online_at:
                online_at[time] += 1
            else:
                online_at[time] = 1


    # Check constraints
    max_users = max(online_at.values()) if online_at else 0

    if max_users > M:
        print("No solution")
    elif max_users == M:
        # We reached M at some point
        print(user_id)
        for i, (s, t) in enumerate(queries):
            # Find which user this query belongs to
            for j, (start, end) in enumerate(users):
                if start <= s <= end:
                    print(j + 1)
                    break
    else:
        print("No solution")

