def solve():
    n, M, T = map(int, input().split())
    queries = []
    for _ in range(n):
        time_str = input().strip()
        queries.append((parse_time(time_str), T))

    # We'll track for each user: (start, end)
    users = []  # list of tuples (start, end)
    user_id = 1

    # Track which users are online at each time
    online_at = {}

    for i, (s, t) in enumerate(queries):
        end = s + t - 1

        # Try to assign to an existing user whose interval contains the query time
        assigned = False
        for j, (start, end_user) in enumerate(users):
            # Check if the query time is within this user's interval
            if start <= s <= end_user:
                # This user already includes this query time
                # So we can assign this query to this user
                users[j] = (min(start, s), max(end_user, end))
                assigned = True
                break

        if not assigned:
            # Create new user
            users.append((s, end))
            user_id += 1

        # Update online_at
        for time in range(s, end + 1):
            if time in online_at:
                online_at[time] += 1
            else:
                online_at[time] = 1

    # Check constraints
    max_users = max(online_at.values()) if online_at else 0

    if max_users > M:
