import sys

sys.setrecursionlimit(10000)

def main():
    n = int(sys.stdin.readline())
    tree = [[] for _ in range(n + 1)]
    c_values = [0] * (n + 1)
    for i in range(1, n + 1):
        p, c = map(int, sys.stdin.readline().split())
        tree[p].append(i)
        c_values[i] = c

    # Perform post-order traversal
    post_order = []
    def dfs(u):
        post_order.append(u)
        for v in tree[u]:
            dfs(v)

    dfs(1)

    # Assign values in decreasing order
    a = [0] * (n + 1)
    for i in range(n, 0, -1):
        a[post_order[i - 1]] = i

    # Verify
    def verify():
        for i in range(1, n + 1):
            cnt = 0
            # Count vertices in subtree of i with value < a[i]
            def dfs_verify(u):
                nonlocal cnt
                if u == i:
                    # vertex i itself
                    return
                if a[u] < a[i]:
                    cnt += 1
                for v in tree[u]:
