import sys
from math import comb

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    s = data[2] if len(data) > 2 else ""

    # Count unique characters
    unique_chars = len(set(s))

    if unique_chars == n:
        # All characters are distinct
        # We can get C(n, l) subsequences of length l
        # Use the longest subsequences first
        for length in range(n, -1, -1):
            max_subseq = comb(n, length)
            if max_subseq <= k:
                k -= max_subseq
                continue
            else:
                total_cost += k * (n - length)
                k = 0
                break
        if k > 0:
            total_cost += k * n

    else:
        # There are duplicate characters
        # We can only get 1 unique subsequence per length
        for length in range(n, -1, -1):
