    for _ in range(n):
        a.append(int(next(it)))

    # Precompute bit positions for each bit (0..29)
    bit_positions = [[] for _ in range(30)]
    for i in range(n):
        if a[i] == 0:
            continue
        for b in range(30):
            if (a[i] >> b) & 1:
                bit_positions[b].append(i)

    out_lines = []
    for _ in range(q):
        x = int(next(it))
        y = int(next(it))
        left_idx = x - 1
        right_idx = y - 1

        # Check if endpoints are 0
        if a[left_idx] == 0 or a[right_idx] == 0:
            out_lines.append("Fou")
            continue

        # Check if there's a 0 between x and y
        has_zero_between = False
        for z in bit_positions[0]:
            if left_idx < z < right_idx:
                has_zero_between = True
                break

        if has_zero_between:
            out_lines.append("Fou")
            continue

        # Check if we can go directly or through intermediate
        if a[left_idx] & a[right_idx] > 0:
            out_lines.append("Shi")
        else:
            # Need to find intermediate
            left_set = a[left_idx]
            right_set = a[right_idx]

            # Check if there's an intermediate that has at least one bit from left and one from right
            found = False

