    # Proper divisors are divisors of n that are not 1 or n

    # Find all proper divisors of n
    divisors = set()
    for i in range(2, n):
        if n % i == 0:
            divisors.add(i)

    # Check if we can find a subset that sums to n-1
    # This is the subset sum problem
    # Since n can be up to 10^9, we need an efficient approach

    # Simple approach: check if we can use a combination of divisors that sum to n-1
    # For small n, we can use brute force

    # For larger n, we can check if we have a divisor close to n-1
    # or if we can use a greedy approach

    # Let's try a simple approach first

    # Check if we have a divisor that is exactly n-1
    if (n-1) in divisors:
        return [(1, n-1)]

    # Try to find a divisor close to n/2
    mid = n // 2
    candidates = sorted(divisors, reverse=True)

    # Try to find a combination
    for i in range(len(candidates)):
        for j in range(i+1, len(candidates)):
            if candidates[i] + candidates[j] == n-1:
                return [(1, candidates[i]), (1, candidates[j])]

    # Try with three divisors
    for i in range(len(candidates)):
        for j in range(i+1, len(candidates)):
            for k in range(j+1, len(candidates)):
