    # If no proper divisors, cannot form solution
    if not divisors:
        return None

    # Sort divisors by size
    sorted_divisors = sorted(divisors, reverse=True)

    # Try a more sophisticated greedy approach
    # Start with the largest divisor and keep adding the largest remaining
    # that doesn't make the sum exceed n-1

    sum_so_far = 0
    result = []

    for d in sorted_divisors:
        # Try to add this divisor
        if sum_so_far + d <= n-1:
            result.append((1, d))
            sum_so_far += d
        else:
            # Skip this divisor
            pass

    # If we haven't reached n-1, maybe we need a different approach
    if sum_so_far < n-1:
        # Try removing the smallest divisor we added and try the next
        if len(result) > 0:
            smallest = min(result, key=lambda x: x[1])[1]
            for i, (a, d) in enumerate(result):
