# Initialize grid (4x4)
occupied = [[False for _ in range(4)] for _ in range(4)]

# Track which rows and columns are deleted
deleted_rows = [False] * 4
deleted_cols = [False] * 4

# Function to check if a row or column is fully occupied
def is_full(row, col):
    # Check if row is fully occupied
    if not deleted_rows[row]:
        full_row = all(occupied[row][c] for c in range(4))
    else:
        full_row = True

    # Check if column is fully occupied
    if not deleted_cols[col]:
        full_col = all(occupied[r][col] for r in range(4))
    else:
        full_col = True

    return full_row, full_col

# Function to place a tile
def place_tile(row, col, tile_type):
    # Check if position is valid (not deleted)
    if deleted_rows[row-1] or deleted_cols[col-1]:
        return False

