        matrix.append(row)
        idx += m

    # Count 2x2 squares with even sum
    even_count = 0
    for i in range(n - 1):
        for j in range(m - 1):
            # Sum of 2x2 square at (i,j)
            total = 0
            for di in range(2):
                for dj in range(2):
                    total += int(matrix[i+di][j+dj])
            if total % 2 == 0:
                even_count += 1

    print(even_count)

if __name__ == "__main__":
    solve()
