def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    w1_seq = []
    w2_seq = []

    idx = 1
    for i in range(n):
        a = int(data[idx])
        idx += 1
        if a > 0:
            w1_seq.append(a)
        else:
            w2_seq.append(-a)

    # Compare total points
    total1 = sum(w1_seq)
    total2 = sum(w2_seq)

    if total1 > total2:
        print("first")
    elif total1 < total2:
        print("second")
    else:
        # Total points are equal, compare sequences lexicographically
        if w1_seq > w2_seq:
            print("first")
        elif w1_seq < w2_seq:
            print("second")
        else:
