import sys

def is_good(point, points):
    """Check if a point is good"""
    n = len(points)
    for i in range(n):
        if i == point:
            continue
        for j in range(i + 1, n):
            if j == point:
                continue
            # Compute vectors from point to i and point to j
            vec1 = [points[i][k] - points[point][k] for k in range(5)]
            vec2 = [points[j][k] - points[point][k] for k in range(5)]

            # Compute dot product
            dot = sum(vec1[k] * vec2[k] for k in range(5))

            if dot > 0:
                return False
    return True

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    points = []
    idx = 1
    for i in range(n):
        coords = list(map(int, data[idx:idx+5]))
        points.append(coords)
        idx += 5

    good_points = []
    for i in range(n):
        if is_good(i, points):
            good_points.append(i + 1)  # 1-indexed

    print(len(good_points))
    for p in good_points:
        print(p)

if __name__ == "__main__":
    solve()
"}

