n, q = map(int, input().split())
a = list(map(int, input().split()))

# dp[i] = bitmask of positions reachable from i
# We'll use an array of integers where each bit represents a position
# dp[i] = 1 << (i-1) initially (only position i is reachable)
dp = [0] * (n + 1)
for i in range(1, n + 1):
    dp[i] = 1 << (i - 1)

# We'll iterate from right to left
# For each i, we check all j > i
for i in range(n, 0, -1):
    for j in range(i + 1, n + 1):
        if a[i - 1] & a[j - 1] > 0:
            dp[i] |= dp[j]

for _ in range(q):
    x, y = map(int, input().split())
    if dp[x] & (1 << (y - 1)):
        print("Shi")
    else:
        print("Fou")
"}

