import math

k, b, n, t = map(int, input().split())

# Special case: k == 1, linear growth
if k == 1:
    # z = 1 + b * n = 1 + b * n
    z = 1 + b * n
    # Need t + b * m >= z
    if t >= z:
        print(0)
    else:
        # m >= (z - t) / b
        print(max(0, (z - t + b - 1) // b))
elif k > 1:
    # Exponential growth
    # z = k^n + b * (k^n - 1) / (k - 1)
    # Use log to compare without computing huge numbers

    # Binary search for minimum m
    low = 0
    high = n
    best = n

    log_k = math.log(k)

    # Calculate log(z)
    if b != 0:
        log_z = log_k * n + math.log(1 + b / (k - 1)) - math.log(k - 1)
    else:
        log_z = log_k * n

    while low <= high:
        mid = (low + high) // 2

        if mid == 0:
            # If mid=0, second experiment = t
            if t >= z:
                best = 0
                high = mid - 1
            else:
                low = mid + 1
        else:
            if b != 0:
                log_second = log_k * mid + math.log(t * (k - 1) + b) - math.log(k - 1)
            else:
                log_second = log_k * mid + math.log(t)

            if log_second >= log_z:
                best = mid
                high = mid - 1
            else:
                low = mid + 1

    print(best)
"}

