import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    f = list(map(int, data[1:1+n]))

    # Build a graph of known mappings
    next_node = [0] * (n + 1)
    for i in range(1, n + 1):
        if f[i - 1] != 0:
            next_node[i] = f[i - 1]

    # Find all cycles
    visited = [False] * (n + 1)
    cycles = []

    for i in range(1, n + 1):
        if f[i - 1] != 0 and not visited[i]:
            cycle = []
            current = i
            while True:
                if visited[current]:
                    break
                visited[current] = True
                cycle.append(current)
                current = next_node[current]
            cycles.append(cycle)

    # We also need to consider nodes that are targets of mappings (not sources)
    targets = set()
    for i in range(1, n + 1):
        if f[i - 1] != 0:
            targets.add(f[i - 1])

    # Find nodes that have f_i = 0 (unknowns)
    unknowns = [i for i in range(1, n + 1) if f[i - 1] == 0]

    # For each unknown node, we need to complete a cycle
    for u in unknowns:
        # Try to complete the cycle from u
        visited_cycle = [False] * (n + 1)
        current = u
        cycle = []
        while True:
            if visited_cycle[current]:
                break
            visited_cycle[current] = True
            cycle.append(current)
            current = next_node[current]

        if len(cycle) >= 1:
            # We need to complete this cycle
            missing = [i for i in range(1, n + 1) if i not in cycle]

            # Build the result
            result = [0] * (n + 1)
            for node in cycle:
                result[node] = next_node[node]

            for idx, node in enumerate(cycle):
                # For unknown nodes in the cycle, we need to assign values from missing
                for m in missing:
                    # Find the first unknown position in the cycle
                    if f[cycle[idx] - 1] == 0:
                        f[cycle[idx] - 1] = m
                        missing.remove(m)
                        break


    # Output
    sys.stdout.write(' '.join(map(str, f[1:])))

if __name__ == '__main__':
    solve()
"}

