def combination(n, k):
    """Calculate C(n, k) = n! / (k! * (n-k)!)
    Returns 0 if n < k or k < 0"""
    if n < k or k < 0:
        return 0
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result

def generate_kth_string(remaining_length, b_remaining, k):
    """Generate the k-th string with remaining_length positions and b_remaining 'b's"
    if b_remaining == 0:
        return 'a' * remaining_length
    if remaining_length == 0:
        return ''

    # Number of strings starting with 'a'
    count_a = combination(remaining_length - 1, b_remaining)

    if k <= count_a:
        return 'a' + generate_kth_string(remaining_length - 1, b_remaining, k)
    else:
        k -= count_a

        if b_remaining == 2:
            return 'ab' + generate_kth_string(remaining_length - 2, 1, k)
        elif b_remaining == 1:
            return 'ba' + generate_kth_string(remaining_length - 2, 1, k)
        else:  # b_remaining == 0
            return 'bb' + generate_kth_string(remaining_length - 2, 0, k)

