# dp[v][u][c][t] = True if current player can win
# c = -1 means no previous character (initial state)
# t = 0 for Max's turn, t = 1 for Lucas's turn
# We'll use a dictionary for dynamic programming

dp = {}

# Base case: no moves available
for v in range(1, n+1):
    for u in range(1, n+1):
        # Max's turn, no previous character - Max loses immediately
        dp[(v, u, -1, 0)] = False
        # Lucas's turn, no previous character - Lucas loses immediately
        dp[(v, u, -1, 1)] = False

# DP
