            if c == -1:
                # No previous character, can use any character
                dp[(v, u, c, 0)] = False
                for (next_v, next_c) in adj[v]:
                    # Max moves to next_v with character next_c
                    # Now Lucas's turn with previous character next_c
                    if not dp[(next_v, u, ord_char[next_c], 1)]:
                        dp[(v, u, c, 0)] = True
                        break
            else:
                # c is an ASCII value, need to check characters
                dp[(v, u, c, 0)] = False
                for (next_v, next_c) in adj[v]:
