for _ in range(m):
    v, u, c = input().split()
    v = int(v)
    u = int(u)
    adj[v].append((u, c))

# ASCII values for characters
ord_char = {c: ord(c) for c in 'abcdefghijklmnopqrstuvwxyz'}

# Topological sort
indegree = {i: 0 for i in range(1, n+1)}
for v in adj:
    for (u, _) in adj[v]:
        indegree[u] += 1

# Queue for topological sort
queue = deque()
for i in range(1, n+1):
    if indegree[i] == 0:
        queue.append(i)

# Process in reverse topological order (from sinks to sources)
top_order = []
while queue:
    u = queue.popleft()
    top_order.append(u)
    for (v, _) in adj:
        if v == u:
            for (next_u, _) in adj[u]:
                indegree[next_u] -= 1
                if indegree[next_u] == 0:
                    queue.append(next_u)

# Reverse topological order for DP (from sink to source)
top_order.reverse()

