    for (v, _) in adj:
        if v == u:
            for (next_u, _) in adj[u]:
                indegree[next_u] -= 1
                if indegree[next_u] == 0:
                    queue.append(next_u)

# dp[v][u][c][t] = True if current player can win
# c = -1 means no previous character
# t = 0 for Max, t = 1 for Lucas

dp = defaultdict(bool)

# Initialize with default False

# DP from source to sink
for v in top_order:
    for u in range(1, n+1):
        # Max's turn at vertex v, Lucas at vertex u
        for prev_c in range(-1, 26):
            # Check all edges from v
            for (next_v, next_c) in adj[v]:
                if prev_c == -1 or ord_char[next_c] >= prev_c:
                    # If Lucas can't win from (next_v, u, next_c), then Max wins
                    if not dp[(next_v, u, ord_char[next_c], 1)]:
                        dp[(v, u, prev_c, 0)] = True
                        break

        # Lucas's turn at vertex u, Max at vertex v
        for prev_c in range(-1, 26):
            for (next_u, next_c) in adj[u]:
                if prev_c == -1 or ord_char[next_c] >= prev_c:
                    if not dp[(v, next_u, ord_char[next_c], 0)]:
                        dp[(v, u, prev_c, 1)] = True
                        break

# Output results
for i in range(1, n+1):
    row = []
    for j in range(1, n+1):
        if dp[(i, j, -1, 0)]:
            row.append('A')
        else:
            row.append('B')
    print(''.join(row))

