    if n % 2 == 0:
        # For even n, each value must appear exactly 4 times
        for count in counter.values():
            if count != 4:
                return False
        return True
    else:
        # For odd n, one value must appear 1 mod 4 times, others 4 times
        odd_count = 0
        for count in counter.values():
            if count % 4 == 1:
                odd_count += 1
            elif count % 4 != 0:
                return False
        return odd_count == 1

