def get_root(l, r):
    """Return the root of the subtree covering positions [l, r]."""
    return (l + r) // 2


def is_leaf(l, r, pos):
    """Check if position pos is a leaf in the subtree [l, r]."""
    return l == r


def move(l, r, pos, direction):
    """Move from position pos in the subtree [l, r] according to direction."""
    root = get_root(l, r)
    if is_leaf(l, r, pos):
        return pos  # Can't move from a leaf

    # Determine if pos is in left or right subtree
    if pos < root:
        # In left subtree
        if direction == 'L':
            # Left child
            new_l, new_r = l, root - 1
            return get_root(new_l, new_r)
        elif direction == 'R':
            # Right child (can't move to right child from left subtree)
            return pos
        else:  # 'U'
            # Move to parent
            new_l, new_r = l, root - 1
            return get_root(l, r)  # Parent is at root of larger subtree
    else:
        # In right subtree
        if direction == 'R':
            # Right child
            new_l, new_r = root + 1, r
            return get_root(new_l, new_r)
        elif direction == 'L':
            # Left child (can't move to left child from right subtree)
            return pos
        else:  # 'U'
            # Move to parent
            new_l, new_r = root + 1, r
            return get_root(l, r)  # Parent is at root of larger subtree


def solve():
    n, q = map(int, input().split())

    for _ in range(q):
        u = int(input())
        s = input().strip()

        l = 1
        r = n

        for ch in s:
            if ch == 'L':
                l, r = 1, n
                l = move(l, r, u, 'L')
                u = l
            elif ch == 'R':
                l, r = 1, n
                r = move(l, r, u, 'R')
                u = r
            elif ch == 'U':
                l, r = 1, n
                u = move(l, r, u, 'U')
            else:
                # Invalid character, skip
                pass

        print(u)

solve()
