def can_achieve(n, k, a):
    # Create a set to track used powers
    used = set()

    # For each position
    for ai in a:
        # If the current position's value is 0, skip
        if ai == 0:
            continue

        # Try to find powers to make ai
        current = ai
        power = 1  # k^0 = 1

        # Find the largest power of k <= current
        while power <= current:
            power *= k
        power //= k  # Largest power that fits

        # Try to allocate powers greedily
        allocated = 0
        while current > 0:
            # Find the largest power that fits and hasn't been used
            best = 0
            for p in range(power, 0, -1):
                if p <= current and p not in used:
                    best = p
                    break

            # If no suitable power found
            if best == 0:
                return False

            used.add(best)
            current -= best

    return True

T = int(input())
