def compute_gcd(arr):
    from math import gcd
    from functools import reduce
    return reduce(gcd, arr)

def prime_factors(n):
    factors = set()
    if n % 2 == 0:
        factors.add(2)
        while n % 2 == 0:
            n //= 2
    i = 3
    while i * i <= n:
        if n % i == 0:
            factors.add(i)
            while n % i == 0:
                n //= i
        i += 2
    if n > 1:
        factors.add(n)
    return factors

if n == 1:
    # Not possible since n >= 2
    print("NO")
else:
    gcd_all = compute_gcd(a)
    if gcd_all > 1:
        print("YES")
        print(0)
    else:
        total = sum(a)
        if total == 0:
            print("YES")
            print(0)
        else:
            # Find prime divisors of sum
            primes = prime_factors(total)
            if not primes:
                # If sum is 1, we can't make it beautiful
                # Actually sum >= 2 since n >= 2 and a_i >= 1
                # So sum >= 2, which has prime factors
                print("NO")
            else:
                max_k = 0
                for p in primes:
                    count = sum(1 for num in a if num % p == 0)
                    max_k = max(max_k, count)
                if max_k == 0:
                    # No element divisible by any prime divisor of sum
                    print("NO")
                else:
                    # Minimal operations = n - max_k
                    answer = n - max_k
                    print("YES")
                    print(answer)
