import sys

def solve() -> None:
    n = int(sys.stdin.readline().strip())

    # Find all divisors of n
    divisors = []
    for d in range(2, int(n**0.5) + 1):
        if n % d == 0:
            if d < n:
                divisors.append(d)
            if n // d != d and n // d < n:
                divisors.append(n // d)

    if not divisors:
        print("NO")
        return

    # Sort divisors by size (smallest first)
    divisors.sort()

    # Use greedy algorithm
    remaining = n - 1
    sequence = []

    for d in divisors:
        c = n // d
        a = min(d - 1, remaining // c)
        if a == 0:
            # Not enough remaining, try a different approach
            # We need to find a such that a * c <= remaining and a >= 1
            # We need to find a = remaining // c
            # But a must be at least 1
            a = remaining // c
            if a >= 1:
                # Use a
                sequence.append((a, d))
                remaining -= a * c
            else:
                # No solution
                print("NO")
                return
        else:
            sequence.append((a, d))
            remaining -= a * c

    if remaining == 0:
        print("YES")
        print(len(sequence))
        for a, d in sequence:
            print(a, d)
    else:
        print("NO")

if __name__ == "__main__":
    solve()
