    n = int(input())
    heights = list(map(int, input().split()))

    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            # Check clockwise arc from i to j (i < j)
            i_is_tallest_clockwise = True
            max_height_between = -1
            for k in range(i + 1, j):
                max_height_between = max(max_height_between, heights[k])
                if heights[k] >= heights[i]:
                    i_is_tallest_clockwise = False

            # Check counterclockwise arc from i to j
            i_is_tallest_counterclockwise = True
            for k in range(j + 1, n):
                if heights[k] >= heights[i]:
                    i_is_tallest_clockwise = False
            for k in range(0, i):
                if heights[k] >= heights[i]:
                    i_is_tallest_clockwise = False

            # If hill i is tallest on either arc, then i can see j
            if i_is_tallest_clockwise or i_is_tallest_counterclockwise:
                count += 1

    print(count)

