    events = []
    for _ in range(n):
        line = input().strip()
        if line.startswith('sell'):
            _, x = line.split()
            events.append(('sell', int(x)))
        else:
            _, x = line.split()
            events.append(('win', int(x)))

    # For each x, track if there's a sell event
    has_sell = {}
    for event in events:
        if event[0] == 'sell':
            has_sell[event[1]] = True

    # Track Bob's state
    has_memory_stick = False
    memory_stick_capacity = None
    earnings = 0

    for event in events:
        if event[0] == 'sell':
            # If Bob has the memory stick, sell it
            if has_memory_stick and memory_stick_capacity == event[1]:
                earnings += 2 ** event[1]
                has_memory_stick = False
                memory_stick_capacity = None
        else:
            # Win event
            if has_sell.get(event[1], False):
                # Keep it if there's a sell event for this capacity
                if has_memory_stick:
                    # Already has a memory stick, give away the current one
                    has_memory_stick = False
                    memory_stick_capacity = None
                has_memory_stick = True
                memory_stick_capacity = event[1]
            else:
                # No sell event, give it away immediately
                pass

    print(earnings)

