def compare_lexicographically(seq1, seq2):
    """
    Compare two sequences lexicographically using absolute values.
    Return:
    - 1 if seq1 > seq2
    - -1 if seq1 < seq2
    - 0 if equal
    """
    min_len = min(len(seq1), len(seq2))

    # Find the first position where they differ
    for i in range(min_len):
        if abs(seq1[i]) != abs(seq2[i]):
            return 1 if abs(seq1[i]) > abs(seq2[i]) else -1

    # If all min_len elements are equal, check lengths
    if len(seq1) > len(seq2):
        return 1
    elif len(seq1) < len(seq2):
        return -1
    else:
        return 0  # Sequences are equal


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    points = list(map(int, data[1:1+n]))

    # Build sequences for each wrestler
    w1_seq = []  # Points awarded to wrestler 1
    w2_seq = []  # Points awarded to wrestler 2

    for i in range(n):
        val = points[i]
        if val > 0:
            w1_seq.append(val)
        else:
            w2_seq.append(val)

    # Calculate total points
    total1 = sum(w1_seq)
    total2 = -sum(w2_seq)  # Convert to positive because w2 has negative values

    if total1 > total2:
        print("first")
    elif total1 < total2:
        print("second")
    else:
        # Sums are equal, compare lexicographically
        result = compare_lexicographically(w1_seq, w2_seq)

        if result == 1:
            print("first")
        elif result == -1:
            print("second")
        else:
            # Sequences are equal, compare who performed the last technique
            # Find the indices of the last technique for each
            last_w1_idx = None
            last_w2_idx = None

            for i in range(n):
                if points[i] > 0:
                    last_w1_idx = i + 1  # 1-indexed
                else:
                    last_w2_idx = i + 1

            if last_w1_idx > last_w2_idx:
                print("first")
            else:
                print("second")

if __name__ == "__main__":
    solve()

